"""Learn a quiet-move history prior from cutoffs generated by a specified engine and checkpoint."""
import argparse
from concurrent.futures import ProcessPoolExecutor
import gzip
import json
import os
from pathlib import Path
import random
import sys
import tempfile

import chess
import numpy as np
from scipy.optimize import minimize
from scipy.special import expit

from fit_readout import holdout
from readout_arena import OPTIONS, opening_key
from train_history_prior import write_table

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from gauntlet import Engine, parse_opts


def roots(archive, counts):
    pools = [set(), set()]
    with gzip.open(archive, "rt") as f:
        for line in f:
            game = json.loads(line)
            group = pools[holdout(game["fen"])]
            board = chess.Board(game["fen"])
            for i, move in enumerate(game["moves"]):
                if i % 8 == 0 and len(board.piece_map()) > 5:
                    group.add(opening_key(board.fen()))
                board.push_uci(move)
    pools[1].difference_update(pools[0])
    rng = random.Random(281916)
    return [[s + " 0 1" for s in rng.sample(sorted(pool), count)] for pool, count in zip(pools, counts)]


def collect(args):
    engine, net, boards, path, nodes = args
    os.environ["SEEK_QUIET_PAIRS"] = str(path)
    # The existing match driver expects a binary and weights as separate arguments.
    e = Engine(f"{engine} {net}", parse_opts(OPTIONS))
    try:
        for board in boards:
            e.new_game()
            e.go(board, [], 0, 0, 0, nodes)
    finally:
        e.quit()
    edges = np.fromfile(path, dtype="<u2").reshape(-1, 3).astype(np.int64)
    keys = (edges[:, 0] * 4096 + edges[:, 1]) * 4096 + edges[:, 2]
    return np.unique(keys, return_counts=True)


def samples(pool, engine, net, boards, folder, nodes, workers):
    jobs = [(engine, net, boards[i::workers], folder / f"{i}.bin", nodes) for i in range(workers)]
    parts = list(pool.map(collect, jobs))
    keys = np.concatenate([part[0] for part in parts])
    weights = np.concatenate([part[1] for part in parts])
    unique, inv = np.unique(keys, return_inverse=True)
    counts = np.bincount(inv, weights=weights)
    return unique // (4096 * 4096), unique // 4096 % 4096, unique % 4096, counts


def objective(params, data, penalty):
    phase, win, fail, counts = data
    phase_win = 4096 + phase * 4096 + win
    phase_fail = 4096 + phase * 4096 + fail
    margin = params[win] - params[fail] + params[phase_win] - params[phase_fail]
    total = counts.sum()
    loss = counts @ np.logaddexp(0.0, -margin) / total
    grad = counts * (-expit(-margin)) / total
    gradient = (np.bincount(win, grad, minlength=len(params)) - np.bincount(fail, grad, minlength=len(params))
                + np.bincount(phase_win, grad, minlength=len(params)) - np.bincount(phase_fail, grad, minlength=len(params)))
    return loss + .5 * (penalty * params) @ params, gradient + penalty * params


def main():
    p = argparse.ArgumentParser(description=__doc__)
    for name in ["engine", "parent", "archive", "output"]:
        p.add_argument(name, type=Path)
    p.add_argument("--workers", type=int, default=6)
    p.add_argument("--train", type=int, default=768)
    p.add_argument("--valid", type=int, default=192)
    p.add_argument("--nodes", type=int, default=20000)
    a = p.parse_args()
    if min(a.workers, a.train, a.valid, a.nodes) < 1 or a.output.exists():
        p.error("Use positive budgets and choose a new output path")
    sets = roots(a.archive, (a.train, a.valid))
    with tempfile.TemporaryDirectory() as t, ProcessPoolExecutor(max_workers=a.workers) as pool:
        folder = Path(t)
        engine, net = folder / "engine", folder / "net"
        engine.symlink_to(a.engine.resolve(strict=True))
        net.symlink_to(a.parent.resolve(strict=True))
        tr, va = [samples(pool, engine, net, group, folder, a.nodes, a.workers) for group in sets]
    n = tr[-1].sum()
    if not n or not va[-1].sum():
        raise ValueError("No quiet cutoffs collected")
    init = np.zeros(5 * 4096)
    penalty = np.r_[np.full(4096, 5.0), np.full(4 * 4096, 20.0)] / n
    res = minimize(objective, init, args=(tr, penalty), method="L-BFGS-B", jac=True,
                   options={"maxiter": 400, "gtol": 2e-7, "ftol": 1e-11})
    if not res.success:
        raise RuntimeError(res.message)
    q = np.rint(256 * np.clip(res.x[:4096] + res.x[4096:].reshape(4, 4096), -4, 4)).astype(np.int16)
    valid_loss = objective(np.r_[np.zeros(4096), q.ravel() / 256.], va, 0)[0]
    print(json.dumps(dict(train_pairs=int(n), valid_pairs=int(va[-1].sum()), uniform_loss=np.log(2), trained_loss=valid_loss)))
    write_table(a.output, q)


if __name__ == "__main__":
    main()
